-- Supabase-shaped source schema for the T14 migration rehearsal.
-- GENERATED by scripts/build-source-schema.sh from supabase/migrations on a
-- scratch public.ecr.aws/supabase/postgres:17.11.0.002 container with stubbed
-- auth and storage (fixtures/supabase-stubs.sql). Do not edit by hand.
-- Restores on plain postgres:16 as a superuser: this preamble creates the
-- Supabase roles the policies name and the extensions schema the defaults use.
DO $$
DECLARE r text;
BEGIN
  FOREACH r IN ARRAY ARRAY['anon', 'authenticated', 'service_role', 'supabase_admin'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
      EXECUTE format('CREATE ROLE %I NOLOGIN', r);
    END IF;
  END LOOP;
END $$;
CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE PUBLICATION supabase_realtime;

